    /**
     * Close, in order of their to-dates, every open period (neither closed nor soft-closed) whose to-date plus the
     * grace days is before the today, as a close by hand would, each recorded as closed automatically; none when the
     * grace days are off (null).
     */
    @Transactional
    public void autoClose(String sheetId, String user, LocalDate today, Integer graceDays) {
        if (graceDays == null) {
            return;
        }
        if (sheets.lockById(sheetId) == 0) {
            throw new SheetNotFoundException(sheetId);
        }
        list(sheetId).stream()
                .filter(p -> !p.isClosed() && !p.isSoftClosed() && p.getToDate().plusDays(graceDays).isBefore(today))
                .sorted(Comparator.comparing(Period::getToDate))
                .forEach(p -> closeNow(sheetId, user, p, true));
    }

    private Period closeNow(String sheetId, String user, Period period, boolean auto) {
        period.close(rollup.dueTotalsBetween(sheetId, period.getFromDate(), period.getToDate()));
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
                + " total=" + saved.getClosedTotal().toPlainString() + (auto ? " auto=yes" : ""));
        return saved;
    }

    /**
     * Reopen a closed or soft-closed period, making its due-total live again; refused unless the user's role may reopen
     * and it is closed or soft-closed.
     */
    @Transactional
    public Period reopen(String sheetId, String user, String name) {
        if (sheets.lockById(sheetId) == 0) {
            throw new SheetNotFoundException(sheetId);
        }
        Period period = periods.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> new PeriodNotFoundException(sheetId, name));
        if (!roles.may(sheetId, user, "reopen")) {
            throw new PeriodReopenForbiddenException(name, user);
        }
        if (!period.isClosed() && !period.isSoftClosed()) {
            throw new PeriodNotClosedException(name);
        }
        period.reopen();
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
        return saved;
    }

    /** The name of the period the date falls in; empty when it is in none. */
    public Optional<String> nameOn(String sheetId, LocalDate date) {
        return list(sheetId).stream().filter(p -> p.contains(date)).map(Period::getName).findFirst();
    }

    /** Whether the date falls in a soft-closed period of the sheet. */
    public boolean softClosedOn(String sheetId, LocalDate date) {
        return list(sheetId).stream().anyMatch(p -> p.isSoftClosed() && p.contains(date));
    }

    /**
     * Refuse a change to a claim due by any of the dates when one falls in a closed period. The sheet is locked
     * until the caller's transaction ends, so a period cannot close while the change is made.
     */
    @Transactional
    public void requireOpen(String sheetId, LocalDate... dates) {
        if (sheets.lockById(sheetId) == 0) {
            throw new SheetNotFoundException(sheetId);
        }
        for (Period period : list(sheetId)) {
            for (LocalDate date : dates) {
                if (period.isClosed() && period.contains(date)) {
                    throw new PeriodClosedException(period.getName(), date);
                }
            }
        }
    }
}
package net.officefloor.hq.app.period;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

/** The periods of a sheet. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/periods")
@Validated
public class PeriodController {

    /**
     * A period as shown, its dates as yyyy-mm-dd; once closed, the due-total fixed then (null while open) and each
     * person's due-total for it fixed then, by person id (empty while open).
     */
    public record PeriodView(Long id, String name, String from, String to, boolean closed, boolean softClosed,
            String closedTotal,
            Map<Long, String> personTotals) {

        static PeriodView of(Period period) {
            Map<Long, String> personTotals = new TreeMap<>();
            period.getPersonTotals().forEach((person, total) -> personTotals.put(person, total.toPlainString()));
            return new PeriodView(period.getId(), period.getName(), period.getFromDate().toString(),
                    period.getToDate().toString(), period.isClosed(), period.isSoftClosed(),
                    period.getClosedTotal() == null ? null : period.getClosedTotal().toPlainString(), personTotals);
        }
    }

    /** A name of no spaces, and the from and to dates as yyyy-mm-dd. */
    public record PeriodRequest(@NotBlank @Pattern(regexp = "\\s*\\S{1,100}\\s*") String name,
            @NotNull @Pattern(regexp = "\\s*\\d{4}-\\d{2}-\\d{2}\\s*") String from,
            @NotNull @Pattern(regexp = "\\s*\\d{4}-\\d{2}-\\d{2}\\s*") String to) {

        static LocalDate date(String value) {
            try {
                return LocalDate.parse(value.trim());
            } catch (DateTimeParseException e) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Not a date: " + value.trim());
            }
        }
    }

    private final PeriodService service;

    public PeriodController(PeriodService service) {
        this.service = service;
    }

    /** The sheet's periods in date order. */
    @GetMapping
    public List<PeriodView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.list(sheetId.trim()).stream().map(PeriodView::of).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PeriodView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PeriodRequest request) {
        return PeriodView.of(service.add(sheetId.trim(), user.trim(), request.name().trim(),
                PeriodRequest.date(request.from()), PeriodRequest.date(request.to())));
    }

    /** The from and to dates of a generate, as yyyy-mm-dd. */
    public record GenerateRequest(@NotNull @Pattern(regexp = "\\s*\\d{4}-\\d{2}-\\d{2}\\s*") String from,
            @NotNull @Pattern(regexp = "\\s*\\d{4}-\\d{2}-\\d{2}\\s*") String to) {
    }

    /** Generate a period per calendar month between the dates; the periods made. Refused when to is before from. */
    @PostMapping("/generate")
    public List<PeriodView> generate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid GenerateRequest request) {
        return service.generate(sheetId.trim(), user.trim(), PeriodRequest.date(request.from()),
                PeriodRequest.date(request.to())).stream().map(PeriodView::of).toList();
    }

    /** Close a period, fixing its due-total; refused when it is already closed. */
    @PostMapping("/{name}/close")
    public PeriodView close(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @NotBlank @Size(max = 100) String name,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(service.close(sheetId.trim(), user.trim(), name.trim()));
    }

    /** Soft-close a period, fixing its figures while its claims can still change; refused when closed or soft-closed. */
    @PostMapping("/{name}/soft-close")
    public PeriodView softClose(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @NotBlank @Size(max = 100) String name,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(service.softClose(sheetId.trim(), user.trim(), name.trim()));
    }

    /** Reopen a closed period, making its due-total live again; refused for a non-steward or a period not closed. */
    @PostMapping("/{name}/reopen")
    public PeriodView reopen(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @NotBlank @Size(max = 100) String name,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(service.reopen(sheetId.trim(), user.trim(), name.trim()));
    }
}

package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Keeps the sheet's settings: its clerk limit, its floor, its terms and each grade's, each grade's grace days, its late percent, its cap, its proof threshold and each grade's, each
 * dated (kept from a from-date); and its policy date, its period numbering from, its entry date, its grace days, its pot, its parent sheet and
 * its permission matrix, not dated.
 */
@Service
public class SettingService {

    /** The grades that may have their own terms. */
    public static final List<String> GRADES = List.of("A", "B", "C");

    private final SheetRepository sheets;
    private final Audit audit;
    private final RollupService rollup;

    public SettingService(SheetRepository sheets, Audit audit, RollupService rollup) {
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    public Sheet get(String sheetId) {
        return sheets.findById(sheetId).orElseThrow(() -> new SheetNotFoundException(sheetId));
    }

    /**
     * Set the clerk limit from the date (null: the sheet's today); a null limit means no limit. Every save is
     * recorded, even of the same value.
     */
    @Transactional
    public Sheet setClerkLimit(String sheetId, String user, BigDecimal limit, LocalDate from) {
        return record(sheetId, user, Sheet.CLERK_LIMIT, limit == null ? null : limit.toPlainString(), from, false);
    }

    /**
     * Set the floor, the least a live due of a claim dated from the date (null: the sheet's today) can be. Every save
     * is recorded, then the figures it moved.
     */
    @Transactional
    public Sheet setFloor(String sheetId, String user, BigDecimal floor, LocalDate from) {
        return record(sheetId, user, Sheet.FLOOR, floor.toPlainString(), from, true);
    }

    /**
     * Set the terms from the date (null: the sheet's today), the days after its date a claim dated from then of a grade
     * without its own terms is due by. Every save is recorded, even of the same value. Claims already added keep their
     * due-by.
     */
    @Transactional
    public Sheet setTerms(String sheetId, String user, int terms, LocalDate from) {
        return record(sheetId, user, Sheet.TERMS, String.valueOf(terms), from, false);
    }

    /** The grades with their own terms in force on the sheet's today, in grade order; a grade not in it uses the sheet's terms. */
    public Map<String, Integer> gradeTerms(Sheet sheet) {
        Map<String, Integer> terms = new LinkedHashMap<>();
        for (String grade : GRADES) {
            sheet.gradeTermsOn(grade, sheet.getToday()).ifPresent(t -> terms.put(grade, t));
        }
        return terms;
    }

    /** The terms in force for a claim dated on the date of a person of the grade: the grade's own, else the sheet's. */
    public int termsFor(String sheetId, String grade, LocalDate date) {
        return get(sheetId).termsFor(grade, date);
    }

    /**
     * Set a grade's own terms from the date (null: the sheet's today). Every save is recorded, even of the same value.
     * Claims already added keep their due-by.
     */
    @Transactional
    public Sheet setGradeTerms(String sheetId, String user, String grade, int terms, LocalDate from) {
        return record(sheetId, user, Sheet.gradeTermsKey(grade), String.valueOf(terms), from, false);
    }

    /**
     * Set a grade's grace days from the date (null: the sheet's today); null means none. A claim whose person's grade on
     * its date has grace days then goes overdue, and counts its late charge, from its due-by plus them. Every save is
     * recorded, then the figures it moved.
     */
    @Transactional
    public Sheet setGradeGrace(String sheetId, String user, String grade, Integer days, LocalDate from) {
        return record(sheetId, user, Sheet.gradeGraceKey(grade), days == null ? null : days.toString(), from, true);
    }

    /**
     * Set the late percent from the date (null: the sheet's today), what an overdue claim dated from then gains for
     * every full 30 days it is overdue. Every save is recorded, then the figures it moved.
     */
    @Transactional
    public Sheet setLatePct(String sheetId, String user, BigDecimal latePct, LocalDate from) {
        return record(sheetId, user, Sheet.LATE_PCT, latePct.toPlainString(), from, true);
    }

    /**
     * Set the cap from the date (null: the sheet's today), the most a person's due-total can be; a null cap means
     * none. Every save is recorded, then the figures it moved.
     */
    @Transactional
    public Sheet setCap(String sheetId, String user, BigDecimal cap, LocalDate from) {
        return record(sheetId, user, Sheet.CAP, cap == null ? null : cap.toPlainString(), from, true);
    }

    /**
     * Set the proof threshold from the date (null: the sheet's today): a claim dated from then whose due is above it
     * cannot be settled or approved without a proof; a null threshold means none. Every save is recorded, even of the
     * same value.
     */
    @Transactional
    public Sheet setProofThreshold(String sheetId, String user, BigDecimal threshold, LocalDate from) {
        return record(sheetId, user, Sheet.PROOF_THRESHOLD, threshold == null ? null : threshold.toPlainString(), from,
                false);
    }

    /**
     * Set a grade's own proof threshold from the date (null: the sheet's today): a claim dated from then of a person
     * of the grade (on its date) is weighed against it in place of the sheet's; a null threshold means none (the
     * sheet's applies). Every save is recorded, even of the same value.
     */
    @Transactional
    public Sheet setGradeProofThreshold(String sheetId, String user, String grade, BigDecimal threshold,
            LocalDate from) {
        return record(sheetId, user, Sheet.gradeProofThresholdKey(grade),
                threshold == null ? null : threshold.toPlainString(), from, false);
    }

    /**
     * Set the note threshold from the date (null: the sheet's today): a claim dated from then whose due is above it
     * cannot be opened with an empty note; a null threshold means none. Every save is recorded, even of the same value.
     */
    @Transactional
    public Sheet setNoteThreshold(String sheetId, String user, BigDecimal threshold, LocalDate from) {
        return record(sheetId, user, Sheet.NOTE_THRESHOLD, threshold == null ? null : threshold.toPlainString(), from,
                false);
    }

    /**
     * Record a dated setting's value from the date (null: the sheet's today), replacing one recorded from that date,
     * then the SETTING_CHANGED record (with the from-date when one was given) and, when the setting moves figures,
     * the figures it moved.
     */
    private Sheet record(String sheetId, String user, String key, String value, LocalDate from, boolean movesFigures) {
        Sheet sheet = get(sheetId);
        RollupService.Snapshot before = movesFigures ? rollup.snapshot(sheetId) : null;
        sheet.record(key, from != null ? from : sheet.getToday(), value);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + key + " value="
                + (value == null ? "" : value) + (from == null ? "" : " from=" + from));
        if (movesFigures) {
            rollup.recordChanges(sheetId, user, before);
        }
        return saved;
    }
    /**
     * Set the policy date, which decides how each claim's live figures round; null means the sheet's today. Every save
     * is recorded, even of the same value, then the figures it moved.
     */
    @Transactional
    public Sheet setPolicyDate(String sheetId, String user, LocalDate policyDate) {
        Sheet sheet = get(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        sheet.setPolicyDate(policyDate);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=policy-date value="
                + (policyDate == null ? "" : policyDate.toString()));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Set the roles (comma separated) that may take the action; null or blank keeps the standing rule. Every save is
     * recorded, even of the same value.
     */
    @Transactional
    public Sheet setPermission(String sheetId, String user, String action, String roles) {
        Sheet sheet = get(sheetId);
        sheet.setPermission(action, roles);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=perm-" + action + " value="
                + (roles == null ? "" : roles));
        return saved;
    }

    /** Set the grace days; null means off. Every save is recorded, even of the same value. */
    @Transactional
    public Sheet setGraceDays(String sheetId, String user, Integer graceDays) {
        Sheet sheet = get(sheetId);
        sheet.setGraceDays(graceDays);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=grace-days value="
                + (graceDays == null ? "" : graceDays.toString()));
        return saved;
    }

    /** Set the pot, shared out over each balanced pool's members; null means none. Every save is recorded, even of the same value. */
    @Transactional
    public Sheet setPot(String sheetId, String user, BigDecimal pot) {
        Sheet sheet = get(sheetId);
        sheet.setPot(pot);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=pot value="
                + (pot == null ? "" : pot.toPlainString()));
        return saved;
    }

    /**
     * Set the parent sheet, whose rates a grade with none in force on a date here falls back on; null means none.
     * Refused for the sheet itself, a sheet that has this sheet as an ancestor, and a sheet never loaded. Every save
     * is recorded, even of the same value, then the figures it moved.
     */
    @Transactional
    public Sheet setParent(String sheetId, String user, String parent) {
        Sheet sheet = get(sheetId);
        if (parent != null) {
            if (parent.equals(sheetId)) {
                throw new ParentRefusedException(sheetId, parent, "a sheet cannot be its own parent");
            }
            Sheet ancestor = sheets.findById(parent)
                    .orElseThrow(() -> new ParentRefusedException(sheetId, parent, "it has never been loaded"));
            Set<String> seen = new HashSet<>();
            while (ancestor != null && seen.add(ancestor.getId())) {
                if (sheetId.equals(ancestor.getParent())) {
                    throw new ParentRefusedException(sheetId, parent, "it has this sheet as an ancestor");
                }
                ancestor = ancestor.getParent() == null ? null : sheets.findById(ancestor.getParent()).orElse(null);
            }
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        sheet.setParent(parent);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=parent value="
                + (parent == null ? "" : parent));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Set the period numbering from; null means off. Every save is recorded, even of the same value. Claims already
     * opened keep their numbers.
     */
    @Transactional
    public Sheet setPeriodNumberingFrom(String sheetId, String user, LocalDate from) {
        Sheet sheet = get(sheetId);
        sheet.setPeriodNumberingFrom(from);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=period-numbering-from value="
                + (from == null ? "" : from.toString()));
        return saved;
    }

    /**
     * Set the entry date, the default date of a new claim in place of the sheet's today; null means off. Every save is
     * recorded, even of the same value. Claims already added keep their dates.
     */
    @Transactional
    public Sheet setEntryDate(String sheetId, String user, LocalDate entryDate) {
        Sheet sheet = get(sheetId);
        sheet.setEntryDate(entryDate);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=entry-date value="
                + (entryDate == null ? "" : entryDate.toString()));
        return saved;
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.Sheet;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The sheet's settings. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/settings")
@Validated
public class SettingController {

    /**
     * The settings as shown, each dated one as in force on the sheet's today: the clerk limit with two decimals, null
     * when there is none; the floor with two decimals; the terms in whole days; each grade's own terms in whole days,
     * by grade (a grade without its own is left out); the late percent with two decimals; the policy date as
     * yyyy-mm-dd, null when blank (the sheet's today); the period numbering from as yyyy-mm-dd, null when blank (off);
     * the entry date as yyyy-mm-dd, null when blank (off); the cap with two decimals, null when there is none; the grace days in whole days, null when blank (off); the proof threshold with two decimals, null when there is none; the note threshold with two decimals, null when there is none; the pot with two decimals, null when there is none; the parent sheet's id, null when there is none;
     * the permission matrix, by action (open, settle, void, reassign, close, reopen), the roles entered for it comma
     * separated, null when blank (the standing rule).
     * Then every value recorded of each dated setting, by key (clerk-limit, floor, terms, terms-A, terms-B, terms-C,
     * grace-A, grace-B, grace-C, late-pct, cap, proof-threshold, proof-threshold-A, proof-threshold-B, proof-threshold-C, note-threshold), from-date first to last.
     */
    public record SettingsView(String clerkLimit, String floor, int terms, Map<String, Integer> gradeTerms,
            String latePct, LocalDate policyDate, LocalDate periodNumberingFrom, LocalDate entryDate, String cap,
            Integer graceDays, String proofThreshold, String noteThreshold, String pot, String parent, Map<String, String> permissions, Map<String, List<DatedValue>> dated) {

        static SettingsView of(Sheet sheet, Map<String, Integer> gradeTerms) {
            LocalDate today = sheet.getToday();
            Map<String, List<DatedValue>> dated = new LinkedHashMap<>();
            sheet.datedSettings().forEach((key, values) -> dated.put(key,
                    values.stream().map(d -> new DatedValue(d.getFromDate(), d.getValue())).toList()));
            Map<String, String> permissions = new LinkedHashMap<>();
            Sheet.PERMISSION_ACTIONS.forEach(action -> permissions.put(action, sheet.permission(action)));
            return new SettingsView(shown(sheet.getClerkLimit()), shown(sheet.floorOn(today)), sheet.termsOn(today),
                    gradeTerms, shown(sheet.latePctOn(today)), sheet.getPolicyDate(), sheet.getPeriodNumberingFrom(),
                    sheet.getEntryDate(), shown(sheet.getCap()), sheet.getGraceDays(), shown(sheet.proofThresholdOn(today)),
                    shown(sheet.noteThresholdOn(today)), shown(sheet.getPot()), sheet.getParent(), permissions,
                    dated);
        }

        private static String shown(BigDecimal value) {
            return value == null ? null : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
        }
    }

    /** A dated setting's value (null: none) from its from-date. */
    public record DatedValue(LocalDate from, String value) {
    }

    /**
     * A clerk limit of 0.00 or more with up to two decimals, blank or missing meaning no limit, from the date (missing:
     * the sheet's today).
     */
    public record SettingsRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String clerkLimit,
            LocalDate from) {

        BigDecimal clerkLimitValue() {
            return clerkLimit == null || clerkLimit.isBlank() ? null
                    : new BigDecimal(clerkLimit.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /** A floor of 0.00 or more with up to two decimals, from the date (missing: the sheet's today). */
    public record FloorRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,10}(\\.\\d{1,2})?\\s*") String floor,
            LocalDate from) {

        BigDecimal floorValue() {
            return new BigDecimal(floor.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /** Terms of 0 or more whole days, from the date (missing: the sheet's today). */
    public record TermsRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,5}\\s*") String terms,
            LocalDate from) {

        int termsValue() {
            return Integer.parseInt(terms.trim());
        }
    }

    /** Grace days of 0 or more whole days, blank or missing meaning none, from the date (missing: the sheet's today). */
    public record GradeGraceRequest(@Pattern(regexp = "\\s*(\\d{1,5})?\\s*") String grace, LocalDate from) {

        Integer graceValue() {
            return grace == null || grace.isBlank() ? null : Integer.valueOf(grace.trim());
        }
    }

    /** A late percent of 0.00 or more with up to two decimals, from the date (missing: the sheet's today). */
    public record LatePctRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,3}(\\.\\d{1,2})?\\s*") String latePct,
            LocalDate from) {

        BigDecimal latePctValue() {
            return new BigDecimal(latePct.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /**
     * A cap of 0.00 or more with up to two decimals, blank or missing meaning no cap, from the date (missing: the
     * sheet's today).
     */
    public record CapRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String cap,
            LocalDate from) {

        BigDecimal capValue() {
            return cap == null || cap.isBlank() ? null
                    : new BigDecimal(cap.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /**
     * A proof threshold of 0.00 or more with up to two decimals, blank or missing meaning none, from the date
     * (missing: the sheet's today).
     */
    public record ProofThresholdRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String proofThreshold,
            LocalDate from) {

        BigDecimal proofThresholdValue() {
            return proofThreshold == null || proofThreshold.isBlank() ? null
                    : new BigDecimal(proofThreshold.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /**
     * A note threshold of 0.00 or more with up to two decimals, blank or missing meaning none, from the date (missing:
     * the sheet's today).
     */
    public record NoteThresholdRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String noteThreshold,
            LocalDate from) {

        BigDecimal noteThresholdValue() {
            return noteThreshold == null || noteThreshold.isBlank() ? null
                    : new BigDecimal(noteThreshold.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /** The roles that may take an action, comma separated (clerk, steward); blank or missing keeps the standing rule. */
    public record PermissionRequest(
            @Pattern(regexp = "\\s*((clerk|steward)(\\s*,\\s*(clerk|steward))*)?\\s*") String roles) {

        String rolesValue() {
            return roles == null || roles.isBlank() ? null : roles.replaceAll("\\s", "");
        }
    }

    /** A policy date as yyyy-mm-dd; null (blank) means the sheet's today. */
    public record PolicyDateRequest(LocalDate policyDate) {
    }

    /** Grace days of 0 or more whole days; blank or missing means off. */
    public record GraceDaysRequest(@Pattern(regexp = "\\s*(\\d{1,5})?\\s*") String graceDays) {

        Integer graceDaysValue() {
            return graceDays == null || graceDays.isBlank() ? null : Integer.valueOf(graceDays.trim());
        }
    }

    /** A pot of 0.00 or more with up to two decimals; blank or missing means none. */
    public record PotRequest(@Pattern(regexp = "\\s*(\\d{1,10}(\\.\\d{1,2})?)?\\s*") String pot) {

        BigDecimal potValue() {
            return pot == null || pot.isBlank() ? null : new BigDecimal(pot.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /** A parent sheet's id; blank or missing means none. */
    public record ParentRequest(@Size(max = 100) String parent) {

        String parentValue() {
            return parent == null || parent.isBlank() ? null : parent.trim();
        }
    }

    /** A period numbering from as yyyy-mm-dd; null (blank) means off. */
    public record PeriodNumberingFromRequest(LocalDate periodNumberingFrom) {
    }

    /** An entry date as yyyy-mm-dd; null (blank) means off. */
    public record EntryDateRequest(LocalDate entryDate) {
    }

