930	    const url = `/api/sheets/${encodeURIComponent(sheet)}`;
931	    const [settings, roles, delegations] = await Promise.all([
932	      firstValueFrom(this.http.get<SettingsView>(`${url}/settings`, this.session.headers())),
933	      firstValueFrom(this.http.get<RoleView[]>(`${url}/roles`, this.session.headers())),
934	      firstValueFrom(this.http.get<DelegationView[]>(`${url}/delegations`, this.session.headers())),
935	    ]).catch(() => [null, null, null]);
936	    // A later read wins over a slower earlier one.
937	    if (settings && roles && delegations && read === this.reads && this.session.sheet() === sheet) {
938	      this.show(settings);
939	      this.roleList.set(roles);
940	      this.delegations.set(delegations);
